/*
 * Samsung S6E3FC3 (Galaxy A32) brightness/AOR data tables.
 *
 * MECHANICALLY TRANSCRIBED from downstream
 * kernel/downstream/drivers/misc/mediatek/lcm/smcdsd_panel/panels/s6e3fc3_a32_param.h
 * (read-only reference; do NOT edit values here, re-generate from that file).
 *  - s6e3fc3_gamma_table[] = brightness_table_id_03 (param.h lines 785-836),
 *    rev>=3 gamma table selected at s6e3fc3_a32.c:1401-1406; live-measured panel
 *    ID 0x800004 rev 4 takes this path. rev<3 table brightness_table_id_00_02
 *    (param.h lines 731-782) is NOT ported (no rev<3 evidence unit).
 *    Spot values: [0]=2, [128]=422 (173nit), [255]=1023 (420nit), [256]=0,
 *    [486]=528; downstream comment claims 486=1023 but table bytes end at 528
 *    (transcribed exactly as-is, inconsistency preserved and flagged).
 *  - Normal-range AOR (brightness 0..255) is constant {0x63,0x00,0x00,0x18}
 *    for all 256 rows (param.h lines 838-1094); encoded as S6E3FC3_AOR_NORMAL
 *    instead of 256 duplicate rows.
 *  - s6e3fc3_aor_hbm_table[] = HBM rows 256..486 payload bytes (param.h
 *    lines 1096-1326); command byte is always 0x63, sent after AOR_GPARA.
 * HARDWARE-UNPROVEN: no unit has confirmed these values over DSI yet.
 */

